"""Generate immutable public contract, provider pins and compiled profile."""
import hashlib,json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
def canonical(v):return json.dumps(v,sort_keys=True,separators=(',',':'),ensure_ascii=False)
def digest(v):return hashlib.sha256(canonical(v).encode()).hexdigest()
FRAME={'format':'mono1-msb-black1','width':800,'height':480,'stride_bytes':100,'frame_bytes':48000,'bits_per_pixel':1,'tone_levels':2,'tones':{'0':'white','1':'black'},'bit_order':'msb_first','byte_order':'row_major','origin':'top_left','row_direction':'top_to_bottom','column_direction':'left_to_right','compression':'none','rotation_degrees':0,'media_type':'application/vnd.riscrte.epaper.mono1','refresh_modes':['full'],'max_inflight_frames':1,'completion_evidence':'controller_busy_asserted_then_released; optical verification unavailable','transfer':{'kind':'capabilities_artifact','sha256_required':True,'participant_scope_required':True,'size_bytes':48000},'desired':{'delivery_semantics':'convergent','slot':'frame','coalesces_superseded_frames':True}}
props={k:{'const':FRAME[k]} for k in ['format','width','height','stride_bytes']}
props['artifact']={'type':'object','additionalProperties':False,'required':['artifact_id','sha256','size_bytes'],'properties':{'artifact_id':{'type':'string','minLength':10,'maxLength':100},'sha256':{'type':'string','pattern':'^[a-f0-9]*$','minLength':64,'maxLength':64},'size_bytes':{'const':48000}}}
INPUT={'type':'object','additionalProperties':False,'required':list(props),'properties':props}
CONTRACT={'capability_id':'display.epaper.frame','api_version':1,'description':'Convergent 800x480 UC8179 black/white framebuffer; immutable artifact transfer, complete verification before full refresh. Native 1-bit tones only.','frame_spec':FRAME,'operations':{'render':{'input_schema':INPUT,'output_schema':{'type':'object','required':['status','sha256'],'properties':{'status':{'enum':['rendered','failed','unknown']},'sha256':{'type':'string'}}},'evidence_schema':{'type':'object'},'execution_modes':['desired_state'],'effect_semantics':'convergent_state'}}}
PIN={'capability_id':CONTRACT['capability_id'],'api_version':1,'contract_digest':digest(CONTRACT)}
PROFILE={'profile_id':'epaper-800x480','revision':1,'capabilities':[PIN],'services':[],'labels':{'display':'uc8179-800x480-bw'}}
PROVIDER={'provider_id':'riscrte.esp32c6.epaper','revision':1,'implementation_ref':'esp32c6-epaper-v1.0.0','provides':[PIN],'requires':[],'frame_spec':FRAME,'placement_constraints':{'required_facts':{'arch':'riscv32','display':'uc8179-800x480-bw'}}}
def generate():
 out={'contract':CONTRACT,'provider':PROVIDER,'profile':PROFILE,'profile_digest':digest(PROFILE)}
 (ROOT/'catalog.json').write_text(json.dumps(out,indent=2)+'\n')
 header='/* Generated by tools/catalog.py; do not hand-edit. */\n'
 for key,value in [('PROFILE_JSON',canonical(PROFILE)),('PROFILE_DIGEST',digest(PROFILE)),('CONTRACT_DIGEST',digest(CONTRACT)),('FRAME_JSON',canonical(FRAME))]:header+=f'#define {key} {json.dumps(value)}\n'
 (ROOT/'main/catalog.h').write_text(header)
if __name__=='__main__':generate()
